public class Account extends EventSourcedAggregate {
    public void debit(Money amount) {
        if (balance.isLessThan(amount)) throw new InsufficientFundsException();
        apply(new AccountDebited(id, amount, Instant.now()));
    }
    protected void on(AccountDebited event) { balance = balance.subtract(event.amount()); }
}

@CommandHandler
public void handle(TransferCommand cmd) {
    Account source = repository.load(cmd.getFromAccountId());
    source.debit(cmd.getAmount());
    Account target = repository.load(cmd.getToAccountId());
    target.credit(cmd.getAmount());
    repository.save(source);
    repository.save(target);
}

public Product getProduct(String sku) {
